import React, { useState, useEffect, useMemo, useRef } from 'react';
import './TradeView.css';
import icons from '../site/icons';
import TradingViewWidgetWrapper from './TradingViewWidgetWrapper';
import { MarketOverview, TickerTape } from 'react-ts-tradingview-widgets';
import { formatDate } from '../hooks/formatDate';
import TradingViewNews from './TradingViewNews';

// TradingView widgets (embed via iframe or script)
const TradingViewWidget = ({ symbol, height = 400 }) => (
        <TradingViewWidgetWrapper symbol={symbol} height={height} />
);

const useDebouncedValue = (value, delay = 400) => {
    const [debounced, setDebounced] = useState(value);
    useEffect(() => {
        const handler = setTimeout(() => setDebounced(value), delay);
        return () => clearTimeout(handler);
    }, [value, delay]);
    return debounced;
};
const STOCKS = [
    { symbol: 'AAPL', name: 'Apple Inc.' },
    { symbol: 'MSFT', name: 'Microsoft Corp.' },
    { symbol: 'GOOGL', name: 'Alphabet Inc.' },
    { symbol: 'AMZN', name: 'Amazon.com Inc.' },
    { symbol: 'TSLA', name: 'Tesla Inc.' },
    { symbol: 'NVDA', name: 'NVIDIA Corp.' },
    { symbol: 'META', name: 'Meta Platforms Inc.' },
    // Add more as needed
];

const TradeView = () => {
    const [search, setSearch] = useState('');

    const API_TOKEN = process.env.REACT_APP_NEWS_API;
    const NEWS_API = `https://newsapi.org/v2/top-headlines?category=business&apiKey=${API_TOKEN}`;
    const TECHNEWS_API = `https://newsapi.org/v2/top-headlines?sources=techcrunch&apiKey=${API_TOKEN}`;
    const WJS_API = `https://newsapi.org/v2/everything?domains=wsj.com&apiKey=${API_TOKEN}`;
    const BBC_API = `https://newsapi.org/v2/top-headlines?sources=bbc-news&apiKey=${API_TOKEN}`;
    const SEARCHTOPSTORIES_API = `https://newsapi.org/v2/top-headlines?q=${search}&apiKey=${API_TOKEN}`;
    const NEWS_CATEGORIES = [
        { key: 'NEWS', label: 'Global Business', api: NEWS_API },
        { key: 'TECH', label: 'Tech Crunch', api: TECHNEWS_API },
        { key: 'WJS', label: 'Wall Street Journal', api: WJS_API },
        { key: 'BBC', label: 'BBC Business', api: BBC_API },
        { key: 'SEARCHTOPSTORIES', label: 'Search Top Stories', api: SEARCHTOPSTORIES_API }
    ];

    const [selectedCategory, setSelectedCategory] = useState(NEWS_CATEGORIES[0].key);
    const [currentNewsApi, setCurrentNewsApi] = useState(NEWS_CATEGORIES[0].api);
    const [news, setNews] = useState([]);
    const [selectedStory, setSelectedStory] = useState(null);
    const [inputValue, setInputValue] = useState('');
    
    const [favorites, setFavorites] = useState(() =>
        JSON.parse(localStorage.getItem('tradeFavorites')) || []
    );
    const [selected, setSelected] = useState(favorites.length ? favorites[0] : STOCKS[0].symbol);

    const debouncedInput = useDebouncedValue(inputValue, 400);
    useEffect(() => {
        setSearch(debouncedInput);
    }, [debouncedInput]);

    const filteredStocks = useMemo(() =>
        STOCKS.filter(
            s =>
                s.name.toLowerCase().includes(search.toLowerCase()) ||
                s.symbol.toLowerCase().includes(search.toLowerCase())
        ),
        [search]
    );

    // Update currentNewsApi when category or search changes
    useEffect(() => {
        const selectedObj = NEWS_CATEGORIES.find(cat => cat.key === selectedCategory);
        if (selectedObj.key === 'SEARCHTOPSTORIES') {
            setCurrentNewsApi(selectedObj.api); // api string already uses latest search
        } else {
            setCurrentNewsApi(selectedObj.api);
        }
    }, [selectedCategory, search]);

    // Fetch news when currentNewsApi changes
    /*
    useEffect(() => {
        setSelectedStory(null); // Reset selected story when changing category
        fetch(currentNewsApi)
            .then(res => res.json())
            .then(data => setNews(data.articles || []))
            .catch(() => setNews([]));
    }, [currentNewsApi]);
    */
    useEffect(() => {
        localStorage.setItem('tradeFavorites', JSON.stringify(favorites));
    }, [favorites]);
    useEffect(() => {
        //console.log(`TradeView => useEffect => news: ${JSON.stringify(news, null, 2)}`);
    }, [news]);

    // Add/remove favorites
    const toggleFavorite = (symbol) => {
        setFavorites(favorites.includes(symbol)
            ? favorites.filter(f => f !== symbol)
            : [...favorites, symbol]
        );
    };
    const TradeViewStockList = React.memo(({ filteredStocks, selected, setSelected, favorites, toggleFavorite }) => (
        <div className='tradeview-stock-list containerDetail ml-10 mr-10 mb-10 color-soft size20 bg-dark'>
            {filteredStocks.map(stock => (
                <div 
                    onClick={() => setSelected(stock.symbol)} 
                    key={stock.symbol} 
                    className={`button hover tradeview-stock-item bg-dark${selected === stock.symbol ? ' selected' : ''}`}
                >
                    <span>{stock.name} ({stock.symbol})</span>
                    <button
                        className={`favorite-btn${favorites.includes(stock.symbol) ? ' active' : ''}`}
                        onClick={() => toggleFavorite(stock.symbol)}
                        title={favorites.includes(stock.symbol) ? 'Remove from favorites' : 'Add to favorites'}
                    >
                        ★
                    </button>
                </div>
            ))}
        </div>
    ));

    const getNews = () => (
        <div>
            {/* News Category Submenu */}
            <div className='news-category-menu containerDetail p-10 mb-5 ml-5 mr-5'>
                {NEWS_CATEGORIES.map(cat => (
                    <div
                        key={cat.key}
                        className={`containerDetail hover button contentLeft pl-15 pt-10 pb-10 pr-10 flex${NEWS_CATEGORIES.length+1}Column${selectedCategory === cat.key ? ' selected' : ''}`}
                        onClick={() => setSelectedCategory(cat.key)}
                    >
                        {cat.label}
                    </div>
                ))}
                {selectedCategory === 'SEARCHTOPSTORIES' && (
                    <input
                        type='text'
                        placeholder='Search news...'
                        value={inputValue}
                        onChange={e => setInputValue(e.target.value)}
                        className='news-search-input width-100-percent m-5 p-20'
                    />
                )}
            </div>
            {/* Top Stories Menu */}
            <ul className='containerDetail news-menu p-20 ml-5 mr-5'>
                {news.length === 0 && <li className='color-soft'>No news available.</li>}
                {news.slice(0, 8).map((article, idx) => (
                    <li
                        key={idx}
                        className={`contentLeft hover button ${selectedStory === article ? ' selected' : ''}`}
                        onClick={() => setSelectedStory(article)}
                    >
                        <div className='news-source pt-5 pl-10 pr-10'>{`${(selectedCategory === 'TECH' || selectedCategory === 'WJS' || selectedCategory === 'BBC') ? formatDate(article.publishedAt) : article.source?.name}`}</div>
                        <div className='news-title pl-10 pr-10 pb-10'>{article.title}</div>
                    </li>
                ))}
            </ul>
            {/* Story Details */}
            {selectedStory && (
                <div className='news-detail containerDetail m-5 p-20 bg-lite contentLeft'>
                    <div className='news-detail-header'>
                        <h4 className='color-yellow'>{selectedStory.title}</h4>
                        <span className='news-detail-source'>{selectedStory.source?.name}</span>
                        <span className='news-detail-date'>
                            {new Date(selectedStory.publishedAt).toLocaleString()}
                        </span>
                    </div>
                    {selectedStory.urlToImage && (
                        <img
                            src={selectedStory.urlToImage}
                            alt={selectedStory.title}
                            className='news-detail-image'
                            style={{ maxWidth: '100%', borderRadius: '8px', margin: '10px 0' }}
                        />
                    )}
                    <div className='news-detail-description contentLeft'>
                        <p>{selectedStory.description}</p>
                        <p className='news-detail-content'>{selectedStory.content}</p>
                    </div>
                    <a
                        href={selectedStory.url}
                        target='_blank'
                        rel='noopener noreferrer'
                        className='news-detail-link'
                    >
                        Read full story
                    </a>
                </div>
            )}
        </div>
    );

    return (
        <div className='mt--30'>
            <div className=''>
                <div className='color-yellow contentLeft'>
                    <div className='containerDetail m-5 p-20 size20 bg-lite'>
                        {icons.tradeview} Market Watch
                    </div>
                    {/* 
                    <div className='tradeview-widgets'>
                        <div className='containerDetail m-5 color-yellow bg-lite'>
                            <div className='containerDetail p-20 m-5 size20'>Market Overview</div>
                            <TradingViewWidget symbol={selected} height={300} />
                        </div>
                    </div> 
                    */}
                    <div className=''>
                        <div className='containerDetail ml-5 mr-5 mb-5 pt-10 bg-dark'>
                            <div className='ml-5 mr-5'>
                                <TickerTape
                                    symbols={() => STOCKS.map((stock) => stock.symbol)}
                                    theme='dark'
                                    isTransparent={false}
                                    displayMode='adaptive'
                                    showSymbolLogo={true}
                                />
                            </div>
                            <div className='mt--30 ml-5 mr-5'>
                                <TickerTape
                                    symbols={STOCKS.map(stock => ({
                                        proName: `NASDAQ:${stock.symbol}`,
                                        title: stock.name
                                    }))}
                                    theme='dark'
                                    isTransparent={false}
                                    displayMode='adaptive'
                                    showSymbolLogo={true}
                                />
                            </div>
                            <div className='mt--25 mr-5 ml-5'>
                                <MarketOverview
                                    symbols={[
                                        { s: 'NASDAQ:AAPL' },
                                        { s: 'NASDAQ:MSFT' },
                                        { s: 'NASDAQ:GOOGL' }
                                    ]}
                                    theme='dark'
                                    colorTheme='dark'
                                    width='100%'
                                    height={400}
                                    isTransparent={false}
                                    plotLineColorGrowing='#00FF00'
                                    plotLineColorFalling='#FF0000'
                                    gridLineColor='gray'
                                    scaleFontColor='orange'
                                    belowLineFillColorGrowing='#00ff0045'
                                    belowLineFillColorFalling='#ff000030'
                                    symbolActiveColor='#052705'
                                />
                            </div>
                        </div>
                    </div>
                    <div className='containerDetail m-5 bg-lite'>
                        <input
                            type='text'
                            placeholder='Search companies...'
                            value={inputValue}
                            onChange={e => setInputValue(e.target.value)}
                            className='containerDetail size20 p-10 m-10 width--20 color-yellow bg-dark'
                        />
                        <TradeViewStockList
                            filteredStocks={filteredStocks}
                            selected={selected}
                            setSelected={setSelected}
                            favorites={favorites}
                            toggleFavorite={toggleFavorite}
                        />
                    </div>
                    <div className='containerDetail m-5 color-yellow bg-lite p-5'>
                        <div className='containerDetail p-20 size20 m-5 bg-lite'>Stock Vitals: {selected}</div>
                        <TradingViewWidget symbol={selected} height={400} />
                    </div>
                    <div className='containerDetail color-yellow m-5 bg-lite'>
                        <div className='containerDetail color-yellow p-20 size20 m-5 bg-lite'>
                            Favorites
                        </div>
                        <div className='containerDetail p-10 m-5 size20 color-lite bg-dark'>
                            {favorites.length === 0 && <div className='color-soft'>No favorites selected.</div>}
                            {favorites.map(symbol => {
                                const stock = STOCKS.find(s => s.symbol === symbol);
                                return (
                                    <div key={symbol} className={`tradeview-stock-item button hover mb-5 containerDetail p-10 ${selected === symbol ? ' selected' : ''}`} onClick={() => setSelected(symbol)}>
                                        {stock ? `${stock.name} (${stock.symbol})` : symbol}
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </div>
            </div>
            {
                /*
                <div className='m-10'>
                    <div className='tradeview-news'>
                        <div className='containerDetail bg-lite color-yellow'>
                            <div className='containerDetail color-yellow p-20 size20 m-5 contentLeft bg-lite'>
                                Economic News
                            </div>
                            {getNews()}
                        </div>
                    </div>
                </div>
                */
            }
            <div className='containerDetail bg-dark m-5 color-yellow height-400'>
                <TradingViewNews />
            </div>
        </div>
    );
};

export default TradeView;